bounded_host_request.command:
set -euo pipefail
docker image inspect create-videobot:poll-candidate >/dev/null 2>&1 || exit 61
docker run --rm --network none --pull never --entrypoint node create-videobot:poll-candidate -e "
import('./src/runtime/creatorPollingMain.mjs').then(()=>process.exit(0)).catch(e=>{
 const c=String(e?.code??'');
 const m=String(e?.message??'');
 if(c==='ERR_MODULE_NOT_FOUND' && m.includes(\"package 'pg'\"))process.exit(80);
 if(c==='ERR_MODULE_NOT_FOUND' && m.includes('/src/runtime/'))process.exit(81);
 if(c==='ERR_MODULE_NOT_FOUND' && m.includes('/src/telegram/'))process.exit(82);
 if(c==='ERR_MODULE_NOT_FOUND' && m.includes('/src/stickers/'))process.exit(83);
 if(c==='ERR_MODULE_NOT_FOUND' && m.includes('/src/'))process.exit(84);
 if(c==='ERR_MODULE_NOT_FOUND')process.exit(85);
 if(e?.name==='SyntaxError')process.exit(86);
 if(e?.name==='TypeError')process.exit(87);
 if(e?.name==='ReferenceError')process.exit(88);
 process.exit(89);
})"
